-- P9-E (ADR-0052 decision 8, contract `Principal.account_not_recorded`): an access event may carry
-- no recorded account (Redis / Valkey only). Generated by drizzle-kit, then edited by hand for the
-- online-constraint rule (AGENTS.md, ADR-0028): `access_events` may be large, so the new CHECK is
-- added `NOT VALID` (no scan under the migration's ACCESS EXCLUSIVE lock) and validated by the
-- migrate runner in its own statement afterwards (`DEFERRED_VALIDATIONS`,
-- src/db/online-constraints.ts), under SHARE UPDATE EXCLUSIVE only. The final schema is the one
-- of the snapshot (same name and expression, validated).
--
-- The column is added with a constant default: a catalog-only change since PostgreSQL 11, no
-- table rewrite. Every existing row has `db_user` or `db_user_fingerprint` (the former CHECK) and
-- `account_not_recorded = false`, so it satisfies the new CHECK.
ALTER TABLE "access_events" DROP CONSTRAINT "access_events_principal";--> statement-breakpoint
ALTER TABLE "access_events" ADD COLUMN "account_not_recorded" boolean DEFAULT false NOT NULL;--> statement-breakpoint
ALTER TABLE "access_events" ADD CONSTRAINT "access_events_principal" CHECK (num_nonnulls("access_events"."db_user", "access_events"."db_user_fingerprint") + "access_events"."account_not_recorded"::int = 1) NOT VALID;
